#requires -Version 5.1
param([Parameter(Mandatory=$true)][string]$FixtureRoot)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
. (Join-Path $PSScriptRoot '../desktop/update-install.ps1') -FunctionsOnly
$FixtureRoot=Full-Path $FixtureRoot
if ((Split-Path $FixtureRoot -Leaf) -notlike 'chartshub-update-fixture-*') { throw 'Synthetic fixture directory required' }
Assert-Plain $FixtureRoot
$global:ChartsHubFixtureRunning=$false
# Synthetic process enumeration only in this test process, never in production.
function Get-Process { [CmdletBinding()]param([int]$Id) if($global:ChartsHubFixtureRunning){[pscustomobject]@{ProcessName='ChartsHub'}} }
$passed=[Collections.Generic.List[string]]::new()
function Check($Condition,[string]$Message){if(!$Condition){throw $Message}}
function Refuse([scriptblock]$Action,[string]$Pattern){$message=$null;try{& $Action | Out-Null}catch{$message=$_.Exception.Message};Check ($message -and $message -match $Pattern) "Expected refusal $Pattern, got $message"}
function Case([string]$Name,[scriptblock]$Action){& $Action;$passed.Add($Name)}
function Asar([string]$Version,[string]$Name='chartshub-desktop'){
 $package=[Text.Encoding]::UTF8.GetBytes((@{name=$Name;version=$Version}|ConvertTo-Json -Compress))
 $json=[Text.Encoding]::UTF8.GetBytes('{"files":{"package.json":{"size":'+$package.Length+',"offset":"0","unpacked":false}}}')
 $payload=[int]([Math]::Ceiling((4+$json.Length)/4.0)*4);$stream=[IO.MemoryStream]::new();$writer=[IO.BinaryWriter]::new($stream)
 $writer.Write([uint32]4);$writer.Write([uint32]($payload+4));$writer.Write([uint32]$payload);$writer.Write([uint32]$json.Length);$writer.Write($json);$writer.Write((New-Object byte[] ($payload-4-$json.Length)));$writer.Write($package);$writer.Flush();$bytes=$stream.ToArray();$writer.Dispose();$stream.Dispose();return ,$bytes
}
function Zip([string]$File,[string]$Special='',[string]$Version='0.14.27'){
 $stream=[IO.File]::Open($File,[IO.FileMode]::CreateNew);$zip=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create)
 try{
  foreach($item in @(@{name='ChartsHub-win32-x64/ChartsHub.exe';bytes=[Text.Encoding]::UTF8.GetBytes('new synthetic exe')},@{name='ChartsHub-win32-x64/resources/app.asar';bytes=(Asar $Version)},@{name='ChartsHub-win32-x64/locales/fr.pak';bytes=[Text.Encoding]::UTF8.GetBytes('new locale')})){$entry=$zip.CreateEntry($item.name);$output=$entry.Open();try{$output.Write($item.bytes,0,$item.bytes.Length)}finally{$output.Dispose()}}
  if($Special){$name=switch($Special){'traversal'{'ChartsHub-win32-x64/../../escape'}'duplicate'{'ChartsHub-win32-x64/CHARTSHUB.EXE'}'link'{'ChartsHub-win32-x64/link'}'collision'{'ChartsHub-win32-x64/resources'}'reserved'{'ChartsHub-win32-x64/CON.txt'}'ads'{'ChartsHub-win32-x64/file:stream'}'trailing'{'ChartsHub-win32-x64/file.'}'root'{'OtherRoot/file'}'songs'{'ChartsHub-win32-x64/Songs/chart/song.ini'}};$entry=$zip.CreateEntry($name);if($Special -eq 'link'){$entry.ExternalAttributes=0xA0000000};$output=$entry.Open();try{$output.WriteByte(65)}finally{$output.Dispose()}}
 }finally{$zip.Dispose();$stream.Dispose()}
}
function New-Case([string]$Name,[string]$Special='',[string]$Version='0.14.27'){
 $root=Join-Path $FixtureRoot $Name;$parent=Join-Path $root 'destination';$app=Join-Path $parent 'ChartsHub-win32-x64';$data=Join-Path $root 'profile';$cache=Join-Path $data 'updates';$id=[guid]::NewGuid().ToString();$job=Join-Path $cache ('install-'+$id)
 foreach($folder in @($parent,$app,(Join-Path $app 'resources'),$data,$cache,$job)){[IO.Directory]::CreateDirectory($folder)|Out-Null}
 [IO.File]::WriteAllText((Join-Path $app 'ChartsHub.exe'),'old synthetic exe');[IO.File]::WriteAllBytes((Join-Path $app 'resources/app.asar'),(Asar '0.14.26'))
 [IO.File]::WriteAllText((Join-Path $data 'preferences.json'),'user settings fixture');[IO.File]::WriteAllText((Join-Path $parent 'ChartsHub.lnk'),'shortcut fixture')
 $archive=Join-Path $cache 'ChartsHub-win32-x64.zip';Zip $archive $Special $Version
 return [pscustomobject]@{id=$id;applicationDirectory=$app;dataDirectory=$data;cacheDirectory=$cache;jobDirectory=$job;archivePath=$archive;archiveSha256=(File-Hash $archive);archiveBytes=(Get-Item -LiteralPath $archive).Length;currentVersion='0.14.26';version='0.14.27';prior=(Tree-Manifest $app)}
}
Case 'successful atomic swap retains original, profile and shortcut' {
 $c=New-Case 'success';$result=Invoke-UpdateTransaction $c;Check ($result.status -eq 'complete') 'Expected complete';Assert-Manifest (Tree-Manifest $result.backup) $c.prior;Check ((Read-AsarPackage (Join-Path $c.applicationDirectory 'resources/app.asar')).version -eq '0.14.27') 'New version';Check ([IO.File]::ReadAllText((Join-Path $c.dataDirectory 'preferences.json')) -eq 'user settings fixture') 'Profile preserved';Check ([IO.File]::ReadAllText((Join-Path ([IO.Path]::GetDirectoryName($c.applicationDirectory)) 'ChartsHub.lnk')) -eq 'shortcut fixture') 'Shortcut preserved'
}
Case 'published digest mismatch leaves application intact' {$c=New-Case 'hash';$c.archiveSha256='f'*64;Refuse {Invoke-UpdateTransaction $c} 'SHA256';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'published size mismatch leaves application intact' {$c=New-Case 'size';$c.archiveBytes++;Refuse {Invoke-UpdateTransaction $c} 'size';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'wrong archive ASAR version refused before swap' {$c=New-Case 'version' '' '0.14.25';Refuse {Invoke-UpdateTransaction $c} 'identity/version';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
foreach($special in @('traversal','duplicate','link','collision','reserved','ads','trailing','root','songs')){
 Case ('archive guard '+$special) {$c=New-Case $special $special;Refuse {Invoke-UpdateTransaction $c} 'ZIP|Song';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
}
Case 'failure after backup restores complete original' {$c=New-Case 'after-backup';Refuse {Invoke-UpdateTransaction $c {param($step)if($step -eq 'backed-up'){throw 'injected'}}} 'rolled-back';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'failure after installation restores original and retains failed new tree' {$c=New-Case 'after-install';Refuse {Invoke-UpdateTransaction $c {param($step)if($step -eq 'installed'){throw 'injected'}}} 'rolled-back';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior;Check (Test-Path -LiteralPath ($c.applicationDirectory+'.incomplete-'+$c.id)) 'Failed tree retained'}
Case 'concurrent modification before swap remains at original path' {$c=New-Case 'before-concurrent';Refuse {Invoke-UpdateTransaction $c {param($step)if($step -eq 'prepared'){[IO.File]::WriteAllText((Join-Path $c.applicationDirectory 'external.txt'),'external edit')}}} 'changed';Check ([IO.File]::ReadAllText((Join-Path $c.applicationDirectory 'external.txt')) -eq 'external edit') 'Concurrent edit preserved'}
Case 'concurrent modification after swap never overwritten by rollback' {$c=New-Case 'after-concurrent';Refuse {Invoke-UpdateTransaction $c {param($step)if($step -eq 'installed'){[IO.File]::WriteAllText((Join-Path $c.applicationDirectory 'external.txt'),'external edit');throw 'injected'}}} 'recovery-required';Check ([IO.File]::ReadAllText((Join-Path $c.applicationDirectory 'external.txt')) -eq 'external edit') 'Concurrent edit preserved';Assert-Manifest (Tree-Manifest ($c.applicationDirectory+'.backup-'+$c.id)) $c.prior}
Case 'modified backup is preserved and cannot be restored blindly' {$c=New-Case 'backup-concurrent';Refuse {Invoke-UpdateTransaction $c {param($step)if($step -eq 'backed-up'){[IO.File]::WriteAllText((Join-Path ($c.applicationDirectory+'.backup-'+$c.id) 'external.txt'),'external edit');throw 'injected'}}} 'recovery-required';Check (Test-Path -LiteralPath (Join-Path ($c.applicationDirectory+'.backup-'+$c.id) 'external.txt')) 'Changed backup preserved'}
Case 'preexisting stage is never overwritten' {$c=New-Case 'stage';[IO.Directory]::CreateDirectory($c.applicationDirectory+'.new-'+$c.id)|Out-Null;Refuse {Invoke-UpdateTransaction $c} 'destination exists';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'another updater lock is never overwritten or removed' {$c=New-Case 'lock';$lock=Join-Path ([IO.Path]::GetDirectoryName($c.applicationDirectory)) '.chartshub-update.lock';[IO.File]::WriteAllText($lock,'other updater');Refuse {Invoke-UpdateTransaction $c} 'exists|exist';Check ([IO.File]::ReadAllText($lock) -eq 'other updater') 'Foreign lock preserved'}
Case 'running app is not terminated and prevents writes' {$c=New-Case 'running';$global:ChartsHubFixtureRunning=$true;try{Refuse {Invoke-UpdateTransaction $c} 'still running'}finally{$global:ChartsHubFixtureRunning=$false};Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'Songs directory stops update before reading media' {$c=New-Case 'local-songs';[IO.Directory]::CreateDirectory((Join-Path $c.applicationDirectory 'Songs'))|Out-Null;Refuse {Invoke-UpdateTransaction $c} 'Songs data'}
Case 'user data inside app refuses update' {$c=New-Case 'profile-inside';$c.dataDirectory=Join-Path $c.applicationDirectory 'userdata';Refuse {Invoke-UpdateTransaction $c} 'User data';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'hardlinked application file refused' {$c=New-Case 'hardlink';New-Item -ItemType HardLink -Path (Join-Path $c.applicationDirectory 'alias.exe') -Target (Join-Path $c.applicationDirectory 'ChartsHub.exe')|Out-Null;Refuse {Invoke-UpdateTransaction $c} 'Hard-linked'}
Case 'junction ancestor refused without following it' {$c=New-Case 'junction';$link=Join-Path ([IO.Path]::GetDirectoryName($c.applicationDirectory)) 'alias';New-Item -ItemType Junction -Path $link -Target $c.applicationDirectory|Out-Null;try{$c.applicationDirectory=$link;Refuse {Invoke-UpdateTransaction $c} 'Linked path'}finally{Assert-Child $link $FixtureRoot;[IO.Directory]::Delete($link)}}
Case 'truncated ASAR is refused before swap' {$c=New-Case 'asar';[IO.File]::WriteAllBytes((Join-Path $c.applicationDirectory 'resources/app.asar'),[byte[]]@(1,2));$c.prior=Tree-Manifest $c.applicationDirectory;Refuse {Invoke-UpdateTransaction $c} 'stream|ASAR|end'}
Case 'another application identity is refused' {$c=New-Case 'other-app';[IO.File]::WriteAllBytes((Join-Path $c.applicationDirectory 'resources/app.asar'),(Asar '0.14.26' 'other-fixture'));$c.prior=Tree-Manifest $c.applicationDirectory;Refuse {Invoke-UpdateTransaction $c} 'identity/version';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'hardlinked archive is refused before replacement' {$c=New-Case 'archive-hardlink';New-Item -ItemType HardLink -Path (Join-Path $c.cacheDirectory 'alias.zip') -Target $c.archivePath|Out-Null;Refuse {Invoke-UpdateTransaction $c} 'Hard-linked';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'locked application file cannot be overwritten' {$c=New-Case 'locked';$handle=[IO.File]::Open((Join-Path $c.applicationDirectory 'ChartsHub.exe'),[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{Refuse {Invoke-UpdateTransaction $c} 'process|sharing|used|utilis|another'}finally{$handle.Dispose()};Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'unsafe root and path forms are refused' {foreach($file in @('C:\','C:\bad.\x','C:\bad\CON.txt','\\server\share\file')){Refuse {Full-Path $file} 'Unsafe|Ambiguous'}}
function Prepare-Entry($c){
 $helper=Join-Path $c.jobDirectory 'update-install.ps1';[IO.File]::Copy((Join-Path $PSScriptRoot '../desktop/update-install.ps1'),$helper)
 $document=[ordered]@{schema=2;kind='update';id=$c.id;applicationDirectory=$c.applicationDirectory;dataDirectory=$c.dataDirectory;cacheDirectory=$c.cacheDirectory;jobDirectory=$c.jobDirectory;archivePath=$c.archivePath;archiveSha256=$c.archiveSha256;archiveBytes=$c.archiveBytes;currentVersion=$c.currentVersion;version=$c.version;commit=('a'*40);tree=('b'*40);releaseId=901;pid=424242;prior=$c.prior;helperSha256=(File-Hash $helper);createdAt=[DateTimeOffset]::UtcNow.ToString('o')}
 $plan=Join-Path $c.jobDirectory 'plan.json';Write-NewJson $plan $document
 return @{helper=$helper;plan=$plan;sha256=(File-Hash $plan)}
}
$global:ChartsHubFixtureLaunches=0
function Start-Process { [CmdletBinding()]param([string]$FilePath,[string]$WorkingDirectory) Assert-Child $FilePath $FixtureRoot;$global:ChartsHubFixtureLaunches++ }
Case 'entrypoint without normal-shutdown authorization never applies or launches' {$c=New-Case 'unauthorized-entry';$entry=Prepare-Entry $c;$before=$global:ChartsHubFixtureLaunches;& $entry.helper -Plan $entry.plan -PlanSha256 $entry.sha256;Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior;Check ($global:ChartsHubFixtureLaunches -eq $before) 'Unauthorized launch';Check ((Read-Json (Join-Path $c.jobDirectory 'result.json')).status -eq 'failed') 'Expected failure receipt'}
Case 'authorized entrypoint handshakes and applies using only fake launch' {$c=New-Case 'authorized-entry';$entry=Prepare-Entry $c;Write-NewJson (Join-Path $c.jobDirectory 'authorized.json') @{planSha256=$entry.sha256};$before=$global:ChartsHubFixtureLaunches;& $entry.helper -Plan $entry.plan -PlanSha256 $entry.sha256;Check ((Read-Json (Join-Path $c.jobDirectory 'ready.json')).planSha256 -eq $entry.sha256) 'Ready handshake';$observed=Read-Json (Join-Path $c.jobDirectory 'result.json');Check ($observed.status -eq 'complete') ('Expected complete receipt: '+($observed|ConvertTo-Json -Compress));Check ($global:ChartsHubFixtureLaunches -eq $before+1) 'Expected one synthetic launch'}
Case 'changed plan cannot reach the ready handshake' {$c=New-Case 'changed-plan-entry';$entry=Prepare-Entry $c;[IO.File]::AppendAllText($entry.plan,' ');Refuse {& $entry.helper -Plan $entry.plan -PlanSha256 $entry.sha256} 'SHA256';Check (!(Test-Path -LiteralPath (Join-Path $c.jobDirectory 'ready.json'))) 'No ready handshake for changed plan';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
function Rollback-Case([string]$Name){
 $c=New-Case $Name;$entry=Prepare-Entry $c;Write-NewJson (Join-Path $c.jobDirectory 'authorized.json') @{planSha256=$entry.sha256};& $entry.helper -Plan $entry.plan -PlanSha256 $entry.sha256
 $receipt=Read-Json (Join-Path $c.jobDirectory 'result.json');Check ($receipt.status -eq 'complete') 'Initial synthetic updater must complete';$id=[guid]::NewGuid().ToString();$job=Join-Path $c.cacheDirectory ('install-'+$id);[IO.Directory]::CreateDirectory($job)|Out-Null
 return [pscustomobject]@{id=$id;applicationDirectory=$c.applicationDirectory;dataDirectory=$c.dataDirectory;cacheDirectory=$c.cacheDirectory;jobDirectory=$job;currentVersion='0.14.27';version='0.14.26';prior=$receipt.installedManifest;sourceBackup=$receipt.backup;sourceManifest=$receipt.previousManifest;sourceJobDirectory=$c.jobDirectory;sourcePlanSha256=$entry.sha256;sourceReceiptSha256=(File-Hash (Join-Path $c.jobDirectory 'result.json'))}
}
Case 'manual rollback restores only updater-owned backup and keeps the version being left' {$c=Rollback-Case 'manual-success';$result=Invoke-RollbackTransaction $c;Check ($result.status -eq 'complete') 'Expected complete rollback';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.sourceManifest;Assert-Manifest (Tree-Manifest $result.backup) $c.prior;Assert-Manifest (Tree-Manifest $c.sourceBackup) $c.sourceManifest}
Case 'manual rollback rejects changed source receipt' {$c=Rollback-Case 'manual-receipt';[IO.File]::AppendAllText((Join-Path $c.sourceJobDirectory 'result.json'),' ');Refuse {Invoke-RollbackTransaction $c} 'SHA256';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'manual rollback rejects modified backup contents' {$c=Rollback-Case 'manual-backup';[IO.File]::WriteAllText((Join-Path $c.sourceBackup 'external.txt'),'external');Refuse {Invoke-RollbackTransaction $c} 'changed';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior;Check (Test-Path -LiteralPath (Join-Path $c.sourceBackup 'external.txt')) 'Backup edit retained'}
Case 'manual rollback rejects current application edits' {$c=Rollback-Case 'manual-current';[IO.File]::WriteAllText((Join-Path $c.applicationDirectory 'external.txt'),'external');Refuse {Invoke-RollbackTransaction $c} 'changed';Check (Test-Path -LiteralPath (Join-Path $c.applicationDirectory 'external.txt')) 'Current edit retained'}
Case 'failed manual rollback restores the version being left' {$c=Rollback-Case 'manual-failure';Refuse {Invoke-RollbackTransaction $c {param($step)if($step -eq 'installed'){throw 'injected'}}} 'rolled-back';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior;Assert-Manifest (Tree-Manifest $c.sourceBackup) $c.sourceManifest}
Case 'manual rollback never overwrites a concurrent change during recovery' {$c=Rollback-Case 'manual-concurrent';Refuse {Invoke-RollbackTransaction $c {param($step)if($step -eq 'installed'){[IO.File]::WriteAllText((Join-Path $c.applicationDirectory 'external.txt'),'external');throw 'injected'}}} 'recovery-required';Check (Test-Path -LiteralPath (Join-Path $c.applicationDirectory 'external.txt')) 'Concurrent edit retained';Assert-Manifest (Tree-Manifest ($c.applicationDirectory+'.backup-'+$c.id)) $c.prior}
Case 'manual rollback cannot point at an unrelated backup directory' {$c=Rollback-Case 'manual-unrelated';$c.sourceBackup=Join-Path $FixtureRoot 'unrelated';Refuse {Invoke-RollbackTransaction $c} 'proof';Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'manual rollback is blocked while any ChartsHub process is running' {$c=Rollback-Case 'manual-running';$global:ChartsHubFixtureRunning=$true;try{Refuse {Invoke-RollbackTransaction $c} 'still running'}finally{$global:ChartsHubFixtureRunning=$false};Assert-Manifest (Tree-Manifest $c.applicationDirectory) $c.prior}
Case 'verified JSON hashes and parses one held stream while replacement is denied' {
 $file=Join-Path $FixtureRoot 'verified-json.json';[IO.File]::WriteAllText($file,'{"value":"original"}');$digest=File-Hash $file;$global:ChartsHubFixtureOriginalOpen=(Get-Command Open-Regular).ScriptBlock;$global:ChartsHubFixtureOpenCount=0;$global:ChartsHubFixtureWriteDenied=$false
 function Open-Regular([string]$File){$global:ChartsHubFixtureOpenCount++;$stream=& $global:ChartsHubFixtureOriginalOpen $File;try{[IO.File]::WriteAllText($File,'{"value":"changed"}')}catch{$global:ChartsHubFixtureWriteDenied=$true};return $stream}
 try{$value=Read-VerifiedJson $file $digest;Check ($value.value -eq 'original') 'Verified content';Check ($global:ChartsHubFixtureOpenCount -eq 1) 'Single held stream';Check $global:ChartsHubFixtureWriteDenied 'Replacement blocked during hash and parse'}finally{Set-Item -LiteralPath Function:Open-Regular -Value $global:ChartsHubFixtureOriginalOpen}
}
@{passed=@($passed);count=$passed.Count;fixtureOnly=$true;realApplicationTouched=$false}|ConvertTo-Json -Depth 5 -Compress
